function perspective(fov:number,aspect:number,near:number,far:number){let t=1/Math.tan(fov/2),r=1/(near-far);return [t/aspect,0,0,0,0,t,0,0,0,0,(far+near)*r,-1,0,0,2*far*near*r,0]}
