function cube(x:number,y:number,z:number,w:number,h:number,d:number,color:V,glow=0){let X=x-w/2,Y=y-h/2,Z=z-d/2,A:[number,number,number][]= [[X,Y,Z],[X+w,Y,Z],[X+w,Y+h,Z],[X,Y+h,Z],[X,Y,Z+d],[X+w,Y,Z+d],[X+w,Y+h,Z+d],[X,Y+h,Z+d]];let faces=[[4,5,6,7],[1,0,3,2],[0,4,7,3],[5,1,2,6],[3,7,6,2],[0,1,5,4]];let ns:V[]=[[0,0,1],[0,0,-1],[-1,0,0],[1,0,0],[0,1,0],[0,-1,0]];let data:number[]=[];for(let i=0;i<6;i++){let q=faces[i];for(let j of [0,1,2,0,2,3])data.push(...A[q[j]],...ns[i],...color,glow)}return data}
function cylinder(x:number,y:number,z:number,r:number,h:number,color:V,seg=10){let data:number[]=[];for(let i=0;i<seg;i++){let a=i*2*Math.PI/seg,b=(i+1)*2*Math.PI/seg;let pa:V=[x+Math.cos(a)*r,y,z+Math.sin(a)*r],pb:V=[x+Math.cos(b)*r,y,z+Math.sin(b)*r];for(let p of [pa,pb,[x,y,z] as V])data.push(...p,0,1,0,...color,0);let qa:V=[pa[0],y-h,pa[2]],qb:V=[pb[0],y-h,pb[2]];for(let p of [pa,qa,qb,pa,qb,pb])data.push(...p,Math.cos(a),0,Math.sin(a),...color,0)}return data}
function trace(a:[number,number],b:[number,number],width=.34,col=PALETTE.copper,y=.35,emission=.12){let dx=b[0]-a[0],dz=b[1]-a[1],angle=Math.atan2(dz,dx),u=Math.cos(angle),v=Math.sin(angle),nx=-v*width/2,nz=u*width/2,coords:V[]=[[a[0]+nx,y,a[1]+nz],[b[0]+nx,y,b[1]+nz],[b[0]-nx,y,b[1]-nz],[a[0]-nx,y,a[1]-nz]];return [0,1,2,0,2,3].flatMap(k=>[...coords[k],0,1,0,...col,emission])}
/* Wire path helpers: waypoints become smooth raised 3D runs. resample evens out spacing,
   smoothPath is a centripetal Catmull-Rom pass, liftY arcs the run above the board. */
function resample(pts:number[][],step:number){let cum=[0];for(let i=1;i<pts.length;i++)cum.push(cum[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]));let tot=cum[cum.length-1],n=Math.max(2,Math.round(tot/step)),out:number[][]=[],j=0;for(let i=0;i<=n;i++){let d=tot*i/n;while(j<pts.length-2&&cum[j+1]<d)j++;let t=(d-cum[j])/((cum[j+1]-cum[j])||1);out.push([tween(pts[j][0],pts[j+1][0],t),tween(pts[j][1],pts[j+1][1],t)])}return out}
function smoothPath(w:number[][],step:number){let P=[[2*w[0][0]-w[1][0],2*w[0][1]-w[1][1]],...w,[2*w[w.length-1][0]-w[w.length-2][0],2*w[w.length-1][1]-w[w.length-2][1]]];let out:number[][]=[];const dist2=(a:number[],b:number[])=>Math.pow(Math.hypot(a[0]-b[0],a[1]-b[1])+1e-6,.5);for(let s=1;s<P.length-2;s++){let p0=P[s-1],p1=P[s],p2=P[s+1],p3=P[s+2];let t0=0,t1=t0+dist2(p0,p1),t2=t1+dist2(p1,p2),t3=t2+dist2(p2,p3);let n=24;for(let i=0;i<n;i++){let t=t1+(t2-t1)*i/n;let lp=(a:number[],b:number[],ta:number,tb:number)=>[0,1].map(c=>a[c]*(tb-t)/(tb-ta)+b[c]*(t-ta)/(tb-ta));let A1=lp(p0,p1,t0,t1),A2=lp(p1,p2,t1,t2),A3=lp(p2,p3,t2,t3);let B1=lp(A1,A2,t0,t2),B2=lp(A2,A3,t1,t3);out.push(lp(B1,B2,t1,t2))}}out.push(w[w.length-1]);return resample(out,step)}
