(function(){let add=(pts:number[][],kind:string,ri:number)=>{let cum=[0];for(let i=1;i<pts.length;i++)cum.push(cum[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]));spineSegs.push({pts,kind,ri,cum,d0:spineLen});spineLen+=cum[cum.length-1]};for(let ri=0;ri<navRoutes.length;ri++){add(navRoutes[ri].pts,'route',ri);if(ri<navRoutes.length-1)add(linkPts(navRoutes[ri].pts[navRoutes[ri].pts.length-1],navRoutes[ri+1].pts[0]),'link',-1)}add(returnPath,'ret',-1)})();
