function tubeVerts(out:number[],pts:number[][],attr:(i:number)=>number[],r:number,col:V,segs:number){let rings:{p:V;n:V}[][]=[];for(let i=0;i<pts.length;i++){let a=pts[Math.max(0,i-1)],b=pts[Math.min(pts.length-1,i+1)];let T=norm([b[0]-a[0],(b[2]-a[2])||0,b[1]-a[1]]);let B=norm(cross([0,1,0],T as V)),U=cross(T as V,B);let ring:{p:V;n:V}[]=[];for(let k=0;k<segs;k++){let th=k/segs*Math.PI*2,c=Math.cos(th),s=Math.sin(th);let nrm:V=[B[0]*c+U[0]*s,B[1]*c+U[1]*s,B[2]*c+U[2]*s];ring.push({p:[pts[i][0]+nrm[0]*r,pts[i][2]+nrm[1]*r*.92,pts[i][1]+nrm[2]*r],n:nrm})}rings.push(ring)}for(let i=0;i<pts.length-1;i++){for(let k=0;k<segs;k++){let k3=(k+1)%segs;let q=[[i,k],[i+1,k],[i+1,k3],[i,k],[i+1,k3],[i,k3]];for(let [ri,kk] of q){let v=rings[ri][kk];out.push(...v.p,...v.n,...col,0,...attr(ri))}}}}
