add(cube(0,-1.3,0,134,2.2,84,PALETTE.edge,0));add(cube(0,-.13,0,132,.22,82,PALETTE.board,.005));
for(let x of [-61,61])for(let z of [-35,35]){add(cylinder(x,.22,z,2.2,.5,PALETTE.metal,14));add(cylinder(x,.53,z,1.25,.16,[.012,.025,.025],14))}
